// Observation records: the measured section is generated from a capture, never written by hand.
const CSWEET_RECORD_BEGIN = '<!-- csweet:observed:begin -->';
const CSWEET_RECORD_END = '<!-- csweet:observed:end -->';

function csweetRenderRecord(evaluation, meta) {
  const cell = value => {
    const text = typeof value === 'string' ? value : csweetCanonical(value);
    return (text.length > 200 ? text.slice(0, 197) + '...' : text).replace(/\|/g, '\\|').replace(/[\r\n]+/g, ' ');
  };
  const lines = [CSWEET_RECORD_BEGIN,
    '_Generated by the C-Sweet scenario runner from a real Chromium run of the built output. Do not edit this section; ' +
    'rerun `' + meta.command + '` to regenerate it. Interpretation belongs outside it._', '',
    `Build \`sha256:${meta.build}\` · ${meta.browser} · result: **${evaluation.passed ? 'PASS' : 'FAIL'}**`, ''];
  for (const text of evaluation.problems) lines.push(`- Contract problem: ${cell(text)}`);
  if (evaluation.problems.length) lines.push('');
  for (const scenario of evaluation.scenarios) {
    const passed = scenario.checks.filter(c => c.passed).length;
    lines.push(`#### ${scenario.id}: ${scenario.passed ? 'PASS' : 'FAIL'} (${passed}/${scenario.checks.length} checks)`, '',
      '| Check | Criterion | Comparison | Expected | Observed | Evidence (events) | Result |', '|---|---|---|---|---|---|---|');
    for (const c of scenario.checks)
      lines.push(`| ${cell(c.name)} | ${c.criterion ?? ''} | ${c.comparison} | ${cell(c.expected)} | ${cell(c.observed)} | ${c.evidence.join(', ')} | ${c.passed ? 'pass' : 'FAIL' + (c.problem ? ': ' + cell(c.problem) : '')} |`);
    // Timings stay in the capture file only, so rerunning a deterministic build leaves the record unchanged.
    lines.push('', `Events emitted: ${scenario.events.length}`, '', '| # | Type | Data |', '|---|---|---|');
    for (const [index, e] of scenario.events.slice(0, 60).entries())
      lines.push(`| ${index} | ${cell(e.type)} | ${e.data === undefined ? '' : cell(e.data)} |`);
    if (scenario.events.length > 60) lines.push('', `${scenario.events.length - 60} further events are in the machine-readable capture below.`);
    lines.push('');
  }
  lines.push('<details><summary>Machine-readable capture</summary>', '', '```json',
    JSON.stringify(csweetRecordCapture(evaluation, meta.build)), '```', '', '</details>', CSWEET_RECORD_END);
  return lines.join('\n');
}

function csweetReplaceRecord(markdown, block) {
  const begin = markdown.indexOf(CSWEET_RECORD_BEGIN);
  const end = markdown.indexOf(CSWEET_RECORD_END);
  if (begin >= 0 && end > begin) return markdown.slice(0, begin) + block + markdown.slice(end + CSWEET_RECORD_END.length);
  if (begin >= 0 || end >= 0) throw Error('The record has an unmatched csweet:observed marker; restore or remove it.');
  return markdown.replace(/\s*$/, '') + '\n\n## Observed run (generated)\n\n' + block + '\n';
}

